INSERT INTO `wp_termmeta` VALUES (1,5,'quiz_data','a:19:{s:7:\"quiz_id\";a:5:{s:4:\"name\";s:7:\"quiz_id\";s:4:\"type\";s:7:\"integer\";s:8:\"required\";s:4:\"true\";s:5:\"value\";i:5;s:3:\"tab\";s:0:\"\";}s:20:\"quiz_pass_percentage\";a:5:{s:4:\"name\";s:20:\"quiz_pass_percentage\";s:4:\"type\";s:7:\"integer\";s:8:\"required\";s:8:\"required\";s:5:\"value\";i:70;s:3:\"tab\";s:7:\"results\";}s:14:\"hide_questions\";a:5:{s:4:\"name\";s:14:\"hide_questions\";s:4:\"type\";s:8:\"checkbox\";s:8:\"required\";s:0:\"\";s:5:\"value\";a:1:{i:0;s:3:\"yes\";}s:3:\"tab\";s:7:\"results\";}s:14:\"quiz_pass_text\";a:5:{s:4:\"name\";s:14:\"quiz_pass_text\";s:4:\"type\";s:6:\"editor\";s:8:\"required\";s:0:\"\";s:5:\"value\";s:686:\"<a href=\"http://smotra.pbf.hr/wp-content/uploads/2021/10/giphy-1.gif\"><img class=\"alignnone wp-image-438 size-full\" title=\"https://media.giphy.com/media/eIftim3DgrLOGOPeVV/giphy.gif\" src=\"http://smotra.pbf.hr/wp-content/uploads/2021/10/giphy-1.gif\" alt=\"\" width=\"480\" height=\"400\" /></a>\n\n<hr />\n\nVoliš \"kemijati\" s hranom i svojim kolegama i prijateljima soliti pamet o nutritivnim vrijednostima hrane koju jedu.\n<div>Obožavaju te zbog toga ;)</div>\n<div>Želiš li znati još i više? klikni <a href=\"http://www.pbf.unizg.hr/znanstveni_i_strucni_rad/knjige_udzbenici_i_prirucnici/knjiga_100_i_pokoja_vise_crtica_iz_znanosti_o_prehrani\" target=\"_blank\" rel=\"noopener\">ovdje</a></div>\";s:3:\"tab\";s:7:\"results\";}s:14:\"quiz_fail_text\";a:5:{s:4:\"name\";s:14:\"quiz_fail_text\";s:4:\"type\";s:6:\"editor\";s:8:\"required\";s:0:\"\";s:5:\"value\";s:667:\"<a href=\"http://smotra.pbf.hr/wp-content/uploads/2021/10/n1.gif\"><img class=\"aligncenter wp-image-435 size-full\" title=\"https://media.giphy.com/media/LnQo5fFiBElv7rK2Wq/giphy.gif\" src=\"http://smotra.pbf.hr/wp-content/uploads/2021/10/n1.gif\" alt=\"\" width=\"480\" height=\"400\" /></a>\n\n<hr />\n\nNemoj kolegama i prijateljima pripremati hranu!\n<div>Da ne budeš kao Rachel iz \"Prija